template <typename UnionPtrType>
FlowTypeParamsPtr FlowTypeParams::Clone() const {
  switch (tag_) {
    case Tag::kWebApprovalsParams:
      return NewWebApprovalsParams(
          mojo::Clone(*data_.web_approvals_params));
    case Tag::kExtensionApprovalsParams:
      return NewExtensionApprovalsParams(
          mojo::Clone(*data_.extension_approvals_params));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, FlowTypeParams>::value>::type*>
bool FlowTypeParams::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kWebApprovalsParams:
      return mojo::Equals(*(data_.web_approvals_params), *(other.data_.web_approvals_params));
    case Tag::kExtensionApprovalsParams:
      return mojo::Equals(*(data_.extension_approvals_params), *(other.data_.extension_approvals_params));
  }

  return false;
}
